import{_ as e,c as i,o as n,a0 as r}from"./chunks/framework.DKRgXLPU.js";const a=JSON.parse('{"title":"Goal Setting for Elite Athletes","description":"Learn advanced goal-setting strategies used by elite pétanque players to drive continuous improvement and achieve peak performance.","frontmatter":{"title":"Goal Setting for Elite Athletes","description":"Learn advanced goal-setting strategies used by elite pétanque players to drive continuous improvement and achieve peak performance."},"headers":[],"relativePath":"de/blog/elite-goal-setting.md","filePath":"de/blog/elite-goal-setting.md"}');const t=e({name:"de/blog/elite-goal-setting.md"},[["render",function(e,a,t,l,s,h){return n(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="zielsetzung-fur-spitzensportler" tabindex="-1">Zielsetzung für Spitzensportler <a class="header-anchor" href="#zielsetzung-fur-spitzensportler" aria-label="Permalink to &quot;Zielsetzung für Spitzensportler&quot;">​</a></h1><p>Zielsetzung scheint einfach: Man entscheidet, was man will, und arbeitet darauf hin. Doch Zielsetzung auf Spitzenniveau ist differenzierter. Die richtigen Ziele beschleunigen die Entwicklung; die falschen führen zu Frustration und Stagnation.</p><h2 id="uber-die-grundlegenden-ziele-hinaus" tabindex="-1">Über die grundlegenden Ziele hinaus <a class="header-anchor" href="#uber-die-grundlegenden-ziele-hinaus" aria-label="Permalink to &quot;Über die grundlegenden Ziele hinaus&quot;">​</a></h2><p>Die meisten Spieler setzen sich folgende Ergebnisziele: „Die Regionalmeisterschaft gewinnen.“ Diese Ziele bergen Probleme:</p><ul><li>Man kann die Ergebnisse nicht vollständig kontrollieren.</li><li>Sie erzeugen Druck ohne Richtung</li><li>Erfolg oder Misserfolg ist binär.</li><li>Sie geben keine Anleitung für die tägliche Praxis</li></ul><p>Die Zielsetzung auf Spitzenniveau geht tiefer.</p><h2 id="die-zielhierarchie" tabindex="-1">Die Zielhierarchie <a class="header-anchor" href="#die-zielhierarchie" aria-label="Permalink to &quot;Die Zielhierarchie&quot;">​</a></h2><h3 id="stufe-1-traumziele-1-5-jahre" tabindex="-1">Stufe 1: Traumziele (1-5 Jahre) <a class="header-anchor" href="#stufe-1-traumziele-1-5-jahre" aria-label="Permalink to &quot;Stufe 1: Traumziele (1-5 Jahre)&quot;">​</a></h3><p>Ihre größten Ziele:</p><ul><li>&quot;Auf nationaler Ebene antreten&quot;</li><li>&quot;Als Eliteschütze anerkannt werden&quot;</li><li>&quot;Gewinne eine Major-Meisterschaft&quot;</li></ul><p>Sie geben Orientierung und Motivation, sind aber nicht im täglichen Leben umsetzbar.</p><h3 id="stufe-2-leistungsziele-saison-jahr" tabindex="-1">Stufe 2: Leistungsziele (Saison/Jahr) <a class="header-anchor" href="#stufe-2-leistungsziele-saison-jahr" aria-label="Permalink to &quot;Stufe 2: Leistungsziele (Saison/Jahr)&quot;">​</a></h3><p>Messbare Verbesserungen in Ihrem Spiel:</p><ul><li>„Steigerung der Treffsicherheit von 60 % auf 70 %“</li><li>„Reduzierung unnötiger Fehler um 25 %“</li><li>&quot;Entwickeln Sie eine zuverlässige Plombée&quot;</li></ul><p>Diese Faktoren liegen in Ihrer Hand und sind messbar.</p><h3 id="stufe-3-prozessziele-taglich-wochentlich" tabindex="-1">Stufe 3: Prozessziele (täglich/wöchentlich) <a class="header-anchor" href="#stufe-3-prozessziele-taglich-wochentlich" aria-label="Permalink to &quot;Stufe 3: Prozessziele (täglich/wöchentlich)&quot;">​</a></h3><p>Die Maßnahmen, die zu Verbesserungen führen:</p><ul><li>&quot;Vollständige Vorbereitungsroutine vor jedem Wurf&quot;</li><li>&quot;Üben Sie die Visualisierung täglich 10 Minuten lang.&quot;</li><li>&quot;Trainiere deine Schusstechnik 3x pro Woche&quot;</li></ul><p>Diese sind vollständig kontrollierbar und tragen zur Erreichung der Leistungsziele bei.</p><h2 id="das-smart-framework" tabindex="-1">Das SMART+-Framework <a class="header-anchor" href="#das-smart-framework" aria-label="Permalink to &quot;Das SMART+-Framework&quot;">​</a></h2><p>Gehen Sie über die grundlegenden SMART-Ziele hinaus:</p><h3 id="spezifisch" tabindex="-1">Spezifisch <a class="header-anchor" href="#spezifisch" aria-label="Permalink to &quot;Spezifisch&quot;">​</a></h3><p>Nicht „meine Treffsicherheit verbessern“, sondern „eine konstante Demi-Portée entwickeln, die aus 8 Metern Entfernung innerhalb von 30 cm des Ziels landet“.</p><h3 id="messbar" tabindex="-1">Messbar <a class="header-anchor" href="#messbar" aria-label="Permalink to &quot;Messbar&quot;">​</a></h3><p>Legen Sie fest, wie Sie den Fortschritt verfolgen werden:</p><ul><li>Erfolgsquoten in Prozent</li><li>Konsistenzmetriken</li><li>Videoanalyse-Marker</li></ul><h3 id="erreichbar-aber-anspruchsvoll" tabindex="-1">Erreichbar, aber anspruchsvoll <a class="header-anchor" href="#erreichbar-aber-anspruchsvoll" aria-label="Permalink to &quot;Erreichbar, aber anspruchsvoll&quot;">​</a></h3><p>Das Ziel sollte zwar Wachstum erfordern, aber realistisch sein. Ein Schütze mit einer Trefferquote von 60 %, der 65 % anstrebt, kann dies erreichen; 90 % anzustreben ist unrealistisch.</p><h3 id="relevant" tabindex="-1">Relevant <a class="header-anchor" href="#relevant" aria-label="Permalink to &quot;Relevant&quot;">​</a></h3><p>Ziele müssen mit Ihren übergeordneten Bestrebungen in Verbindung stehen und tatsächliche Schwächen angehen, nicht nur das, was leicht zu verbessern ist.</p><h3 id="zeitgebunden" tabindex="-1">Zeitgebunden <a class="header-anchor" href="#zeitgebunden" aria-label="Permalink to &quot;Zeitgebunden&quot;">​</a></h3><p>Klare Fristen setzen:</p><ul><li>„Bis zum Ende der Saison“</li><li>&quot;Innerhalb von 3 Monaten&quot;</li><li>&quot;Bis zur nationalen Meisterschaft&quot;</li></ul><h3 id="personlich-bedeutsam" tabindex="-1">+ Persönlich bedeutsam <a class="header-anchor" href="#personlich-bedeutsam" aria-label="Permalink to &quot;+ Persönlich bedeutsam&quot;">​</a></h3><p>Das Ziel muss DIR wichtig sein, nicht nur deinem Trainer oder deinen Teamkollegen. Innere Motivation hält die Anstrengung aufrecht, wenn die Fortschritte langsam sind.</p><h2 id="prozess-vs-ergebnisorientierung" tabindex="-1">Prozess- vs. Ergebnisorientierung <a class="header-anchor" href="#prozess-vs-ergebnisorientierung" aria-label="Permalink to &quot;Prozess- vs. Ergebnisorientierung&quot;">​</a></h2><h3 id="das-problem-mit-ergebniszielen" tabindex="-1">Das Problem mit Ergebniszielen <a class="header-anchor" href="#das-problem-mit-ergebniszielen" aria-label="Permalink to &quot;Das Problem mit Ergebniszielen&quot;">​</a></h3><p>„Das Spiel gewinnen“ schafft Probleme:</p><ul><li>Angst vor Dingen, die man nicht kontrollieren kann</li><li>Ablenkung von der Hinrichtung</li><li>Alles-oder-nichts-Denken</li><li>Druck ohne Führung</li></ul><h3 id="die-macht-der-prozessziele" tabindex="-1">Die Macht der Prozessziele <a class="header-anchor" href="#die-macht-der-prozessziele" aria-label="Permalink to &quot;Die Macht der Prozessziele&quot;">​</a></h3><p>„Führe meine Vorbereitungsroutine perfekt aus“ bietet:</p><ul><li>Volle Kontrolle</li><li>Klarer Fokus</li><li>Unmittelbares Feedback</li><li>Führt auf natürliche Weise zu bestimmten Ergebnissen.</li></ul><h3 id="das-gleichgewicht" tabindex="-1">Das Gleichgewicht <a class="header-anchor" href="#das-gleichgewicht" aria-label="Permalink to &quot;Das Gleichgewicht&quot;">​</a></h3><p>Nutzen Sie Ergebnisziele zur Motivation und Orientierung. Nutzen Sie Prozessziele für die tägliche Fokussierung und Umsetzung.</p><h2 id="zielsetzung-fur-verschiedene-phasen" tabindex="-1">Zielsetzung für verschiedene Phasen <a class="header-anchor" href="#zielsetzung-fur-verschiedene-phasen" aria-label="Permalink to &quot;Zielsetzung für verschiedene Phasen&quot;">​</a></h2><h3 id="nebensaison" tabindex="-1">Nebensaison <a class="header-anchor" href="#nebensaison" aria-label="Permalink to &quot;Nebensaison&quot;">​</a></h3><p>Fokus auf Entwicklungsziele:</p><ul><li>Technische Verbesserungen</li><li>Körperliche Konditionierung</li><li>Aufbau mentaler Fähigkeiten</li><li>Erweitern Sie Ihre Auswahl an Überwürfen</li></ul><h3 id="vorsaison" tabindex="-1">Vorsaison <a class="header-anchor" href="#vorsaison" aria-label="Permalink to &quot;Vorsaison&quot;">​</a></h3><p>Übergang zur Integration:</p><ul><li>Kombination von Fähigkeiten unter spielähnlichen Bedingungen</li><li>Verbesserungen im freundschaftlichen Wettbewerb testen</li><li>Verfeinerungsstrategien</li></ul><h3 id="wettkampfsaison" tabindex="-1">Wettkampfsaison <a class="header-anchor" href="#wettkampfsaison" aria-label="Permalink to &quot;Wettkampfsaison&quot;">​</a></h3><p>Verlagerung hin zu Leistung und Prozess:</p><ul><li>Die Umsetzung dessen, was Sie entwickelt haben</li><li>Prozessziele für jedes Spiel</li><li>Minimale technische Änderungen</li></ul><h3 id="nach-dem-wettbewerb" tabindex="-1">Nach dem Wettbewerb <a class="header-anchor" href="#nach-dem-wettbewerb" aria-label="Permalink to &quot;Nach dem Wettbewerb&quot;">​</a></h3><p>Reflexion und Planung:</p><ul><li>Analysieren Sie, was funktioniert hat.</li><li>Wachstumsbereiche identifizieren</li><li>Ziele für den nächsten Zyklus setzen</li></ul><h2 id="haufige-fehler-bei-der-zielsetzung" tabindex="-1">Häufige Fehler bei der Zielsetzung <a class="header-anchor" href="#haufige-fehler-bei-der-zielsetzung" aria-label="Permalink to &quot;Häufige Fehler bei der Zielsetzung&quot;">​</a></h2><h3 id="zu-viele-tore" tabindex="-1">Zu viele Tore <a class="header-anchor" href="#zu-viele-tore" aria-label="Permalink to &quot;Zu viele Tore&quot;">​</a></h3><p>Konzentration ist Stärke. Zwei bis drei entscheidende Tore sind besser als zehn verstreute.</p><h3 id="nur-ergebnisziele" tabindex="-1">Nur Ergebnisziele <a class="header-anchor" href="#nur-ergebnisziele" aria-label="Permalink to &quot;Nur Ergebnisziele&quot;">​</a></h3><p>Ohne Prozessziele gibt es keinen Fahrplan.</p><h3 id="keine-flexibilitat" tabindex="-1">Keine Flexibilität <a class="header-anchor" href="#keine-flexibilitat" aria-label="Permalink to &quot;Keine Flexibilität&quot;">​</a></h3><p>Ziele sollten an neue Informationen angepasst werden. Starres Festhalten an überholten Zielen ist reine Zeitverschwendung.</p><h3 id="vergleichsbasierte-ziele" tabindex="-1">Vergleichsbasierte Ziele <a class="header-anchor" href="#vergleichsbasierte-ziele" aria-label="Permalink to &quot;Vergleichsbasierte Ziele&quot;">​</a></h3><p>„Sei besser als [Spieler]“ bedeutet, dass dein Erfolg in die Hände anderer gelegt wird.</p><h3 id="vernachlassigung-mentaler-ziele" tabindex="-1">Vernachlässigung mentaler Ziele <a class="header-anchor" href="#vernachlassigung-mentaler-ziele" aria-label="Permalink to &quot;Vernachlässigung mentaler Ziele&quot;">​</a></h3><p>Technische und physische Ziele stehen im Vordergrund, doch mentale Fähigkeiten entscheiden oft über den Sieg.</p><h2 id="umsetzungsstrategien" tabindex="-1">Umsetzungsstrategien <a class="header-anchor" href="#umsetzungsstrategien" aria-label="Permalink to &quot;Umsetzungsstrategien&quot;">​</a></h2><h3 id="schreibe-sie-auf" tabindex="-1">Schreibe sie auf <a class="header-anchor" href="#schreibe-sie-auf" aria-label="Permalink to &quot;Schreibe sie auf&quot;">​</a></h3><p>Schriftlich festgelegte Ziele werden mit deutlich höherer Wahrscheinlichkeit erreicht.</p><h3 id="regelmaßig-uberprufen" tabindex="-1">Regelmäßig überprüfen <a class="header-anchor" href="#regelmaßig-uberprufen" aria-label="Permalink to &quot;Regelmäßig überprüfen&quot;">​</a></h3><p>Die wöchentliche Überprüfung hält die Ziele präsent und ermöglicht Anpassungen.</p><h3 id="selektiv-teilen" tabindex="-1">Selektiv teilen <a class="header-anchor" href="#selektiv-teilen" aria-label="Permalink to &quot;Selektiv teilen&quot;">​</a></h3><p>Teile es mit denen, die dich unterstützen und nicht untergraben werden.</p><h3 id="erfolg-visualisieren" tabindex="-1">Erfolg visualisieren <a class="header-anchor" href="#erfolg-visualisieren" aria-label="Permalink to &quot;Erfolg visualisieren&quot;">​</a></h3><p>Stellen Sie sich regelmäßig vor, wie Sie Ihre Ziele erreichen – das Gefühl, den Moment.</p><h3 id="fortschritt-verfolgen" tabindex="-1">Fortschritt verfolgen <a class="header-anchor" href="#fortschritt-verfolgen" aria-label="Permalink to &quot;Fortschritt verfolgen&quot;">​</a></h3><p>Was gemessen wird, wird auch gesteuert. Führen Sie Aufzeichnungen.</p><h2 id="wenn-ziele-nicht-erreicht-werden" tabindex="-1">Wenn Ziele nicht erreicht werden <a class="header-anchor" href="#wenn-ziele-nicht-erreicht-werden" aria-label="Permalink to &quot;Wenn Ziele nicht erreicht werden&quot;">​</a></h2><p>Nicht erreichte Ziele sind keine Misserfolge – sie sind Daten:</p><ol><li><strong>Analyse</strong>: Warum wurde dieses Ziel nicht erreicht?</li><li><strong>Lernen</strong>: Was lernst du daraus?</li><li><strong>Anpassen</strong>: Ziel oder Vorgehensweise ändern.</li><li><strong>Weiter</strong>: Beharrlichkeit schlägt Perfektion</li></ol><h2 id="das-mentale-spiel-der-tore" tabindex="-1">Das mentale Spiel der Tore <a class="header-anchor" href="#das-mentale-spiel-der-tore" aria-label="Permalink to &quot;Das mentale Spiel der Tore&quot;">​</a></h2><p>Ziele beeinflussen die Psychologie:</p><ul><li><strong>Zu einfach</strong>: Langeweile, Selbstzufriedenheit</li><li><strong>Zu schwierig</strong>: Angstzustände, Entmutigung</li><li><strong>Genau richtig</strong>: Engagement, Fluss, Wachstum</li></ul><p>Finde die ideale Balance, bei der Ziele herausfordernd, aber nicht überfordernd sind.</p><hr><p>| <em>Verwandtes Thema: <a href="/en/education/goals/">Einführung in die Zielsetzung</a> | <a href="/en/education/goals/smart-goals">SMART Goals</a> | <a href="/en/education/goals/planning">Planung Ihrer Entwicklung</a></em> |</p>',88)])])}]]);export{a as __pageData,t as default};
